    key = jax.random.key(0)
    x = jax.random.uniform(key, CONFIG['shape'], dtype)
    return (x,)


def workload(x):
    inner = CONFIG['sqrt_2_over_pi'] * (x + CONFIG['cubic_coeff'] * jnp.power(x, 3))
    return CONFIG['outer_scale'] * x * (CONFIG['offset'] + jnp.tanh(inner))

